<?php
declare(strict_types=1);
function broadcastLabel(string $status):string{return ['draft'=>'確認中・未登録','development'=>'開発用・未送信','queued'=>'送信キュー登録済み','cancelled'=>'未処理分を停止済み'][$status]??(OUTBOX_STATUS[$status]??$status);}
function broadcastView():string {
 global $config;$id=(int)($_GET['id']??0);$html='<div class="page-title"><div class="eyebrow">ANNOUNCEMENT MAIL</div><h1>大切なお知らせを、みんなへ。</h1><p>開催予定の変更などを、申込時のメールアドレスへ1人ずつ個別に配信します。他の方のアドレスは本文やTo・CCに載せません。</p></div>';
 if($id){$b=one('SELECT * FROM broadcasts WHERE id=?',[$id]);requirev((bool)$b,'一斉メールがありません。');$messages=all('SELECT * FROM broadcast_messages WHERE broadcast_id=? ORDER BY id',[$id]);$audience=obj($b['audience_json']);$html.='<a href="?page=admin_broadcast">← 作成・履歴へ</a><section class="panel"><h2>'.h($b['subject']).'</h2><p>状態：'.h(broadcastLabel($b['status'])).' ／ 対象 '.count($messages).'件 ／ 除外 '.count($audience['excluded']).'件</p><p>対象：'.($b['target']==='all'?'全申込者（欠席申請・取消済みを含む）':'現在の参加予定者のみ').' ／ 送信元：'.h($config['mail_from']??'未設定').'</p><pre class="message-body">'.h($b['body']).'</pre></section>';
  if($b['status']==='draft')$html.='<section class="panel"><h2>内容と対象人数を確認</h2><p>'.($config['mode']==='live'&&!empty($config['mail_enabled'])?'確認後、送信キューへ登録します。送信処理はサーバーの定期実行で進みます。':'現在は開発モードです。保存だけ行い、外部へメールを送りません。').'</p>'.form('broadcast_queue',hidden('id',$id).'<label class="photo-consent"><input name="confirm" type="checkbox" value="yes" required> 件名・本文と対象 '.count($messages).'件を確認しました。</label>'.button('確認して登録する')).'<p><a href="?page=admin_broadcast&amp;edit='.$id.'">内容を修正して確認し直す</a></p></section>';
  $counts=[];foreach($messages as $m)$counts[$m['status']]=($counts[$m['status']]??0)+1;$html.='<section class="panel"><h2>宛先別の状況</h2><p>'.implode(' ／ ',array_map(fn($s)=>h(broadcastLabel($s)).' '.$counts[$s].'件',array_keys($counts))).'</p><p class="mini-note">「メールサーバー受付済」は配信先への到達保証ではありません。処理中・失敗は自動再送しません。</p></section>'.tabler(['登録者','宛先','状態','エラー'],array_map(fn($m)=>[h($m['recipient_name']),h($m['to_email']),h(broadcastLabel($m['status'])),h($m['error_text'])],$messages));
  if($audience['excluded'])$html.='<section class="panel"><h3>除外した対象</h3>'.tabler(['登録者ID','理由'],array_map(fn($e)=>[h($e['user_id']),h($e['reason'])],$audience['excluded'])).'</section>';
  if($b['status']!=='cancelled')$html.='<section class="panel"><h3>未処理分の停止</h3><p>すでに送信処理中・受付済みのメールは取り消せません。</p>'.form('broadcast_cancel',hidden('id',$id).reasons().button('未処理分を停止')).'</section>';return $html;
 }
 $edit=one('SELECT * FROM broadcasts WHERE id=?',[(int)($_GET['edit']??0)]);$html.='<section class="panel"><h2>一斉メールを作成</h2><p class="notice">現在は開発用です。実際の個人情報や連絡文を入れず、架空の内容で操作してください。</p>'.form('broadcast_preview','<label class="field">送信対象<select name="target"><option value="all">全申込者（欠席申請・取消済みを含む）</option><option value="active"'.(($edit['target']??'')==='active'?' selected':'').'>現在の参加予定者のみ</option></select></label>'.input('subject','件名',$edit['subject']??'').'<label class="field">本文<textarea name="body" maxlength="10000" rows="10" required>'.h($edit['body']??'').'</textarea></label><p class="mini-note">問い合わせだけの方は対象に含みません。同じ宛先は1件に集約し、無効なメールアドレスは確認画面で除外理由を表示します。</p>'.button('内容と対象人数を確認する')).'</section><section class="panel"><h2>一斉メールの履歴</h2>';
 foreach(all('SELECT b.*,u.name,(SELECT COUNT(*) FROM broadcast_messages m WHERE m.broadcast_id=b.id) AS recipients FROM broadcasts b JOIN users u ON u.id=b.actor_id ORDER BY b.id DESC') as $b)$html.='<p><a href="?page=admin_broadcast&amp;id='.$b['id'].'">#'.$b['id'].' '.h($b['subject']).'</a> ／ '.$b['recipients'].'件 ／ '.h(broadcastLabel($b['status'])).' ／ '.h($b['created']).' ／ '.h($b['name']).'</p>';
 return $html.'</section>';
}
function broadcastOutboxView():string {
 $html='<section class="panel"><h2>一斉メール</h2><a class="btn" href="?page=admin_broadcast">作成・送信履歴を開く</a>';
 foreach(all("SELECT b.*,(SELECT COUNT(*) FROM broadcast_messages m WHERE m.broadcast_id=b.id) AS recipients FROM broadcasts b WHERE b.status<>'draft' ORDER BY b.id DESC") as $b)$html.='<p><a href="?page=admin_broadcast&amp;id='.$b['id'].'">'.h($b['subject']).'</a> ／ '.$b['recipients'].'件 ／ '.h(broadcastLabel($b['status'])).'</p>';return $html.'</section>';
}
